// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading ensures availability before frame 0
const { fontFamily: montserrat } = loadMontserrat();



export type GameShowTitleCardProps = Record<string, any>;

const GameShowTitleCard: React.FC<GameShowTitleCardProps> = ({
  backgroundColor = "#1e1b4b", // Deep indigo base
  transparentBackground = false,
  durationInSeconds = 5,
  title = "TRUE OR FALSE:",
  subtitle = "BAY AREA REAL ESTATE EDITION",
  accentColor = "#fbbf24", // Gold
  shadowColor = "#9f1239", // Deep ruby red for 3D depth
  sunburstColor = "#4f46e5", // Bright purple/indigo for background rays
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser-safe background color calculation
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Generators ---

  // 1. Continuous slow rotation for the classic game show sunburst background
  const sunburstRotation = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [0, 180] // Slow, constant rotation across the composition
  );

  // 2. Title explosion (spring pop-in with rotation)
  const titleProgress = spring({
    fps,
    frame: frame - 10, // Staggered start
    config: {
      damping: 10,
      stiffness: 90,
      mass: 1.5,
    },
  });

  const titleScale = interpolate(titleProgress, [0, 1], [0.1, 1]);
  const titleRotate = interpolate(titleProgress, [0, 1], [-25, 0]);

  // 3. Subtitle slide up
  const subtitleProgress = spring({
    fps,
    frame: frame - 25, // Appears after title
    config: {
      damping: 12,
      stiffness: 120,
    },
  });

  const subtitleY = interpolate(subtitleProgress, [0, 1], [150, 0]);
  const subtitleOpacity = interpolate(subtitleProgress, [0, 1], [0, 1]);

  // 4. Star pulse (continuous oscillating scale)
  const lightPulse = interpolate(
    Math.sin(frame / 8),
    [-1, 1],
    [0.7, 1.1]
  );

  // --- Visual Effects ---

  // Generating a rigid 3D text shadow array for the title
  const numShadows = 18;
  const textShadows = Array.from({ length: numShadows })
    .map((_, i) => `${i + 1}px ${i + 1}px 0px ${shadowColor}`)
    .join(", ");

  // Responsive scaling baseline
  const minDim = Math.min(width, height);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
        fontFamily: montserrat,
      }}
    >
      {/* Dynamic Sunburst Background */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            // CSS Repeating Conic Gradient creates the 'rays'
            background: `repeating-conic-gradient(from 0deg, transparent 0deg 15deg, ${sunburstColor}60 15deg 30deg)`,
            transform: `scale(2.5) rotate(${sunburstRotation}deg)`,
            transformOrigin: "center center",
            opacity: 0.8,
            transition: "none",
          }}
        />
      )}

      {/* Main Content Layout - Canvas Aware Vertical Center */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          padding: "10%", // Keep elements away from safe zones
          transition: "none",
        }}
      >
        {/* Title Group */}
        <div
          style={{
            transform: `scale(${titleScale}) rotate(${titleRotate}deg)`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            zIndex: 10,
            transition: "none",
          }}
        >
          {/* Animated Accent Stars */}
          <div
            style={{
              position: "absolute",
              top: -80,
              left: -60,
              fontSize: 90,
              transform: `scale(${lightPulse}) rotate(${frame * 2}deg)`,
              color: accentColor,
              textShadow: `0 0 30px ${accentColor}`,
              transition: "none",
            }}
          >
            ✦
          </div>
          <div
            style={{
              position: "absolute",
              bottom: -50,
              right: -60,
              fontSize: 70,
              transform: `scale(${lightPulse}) rotate(${-frame * 1.5}deg)`,
              color: accentColor,
              textShadow: `0 0 30px ${accentColor}`,
              transition: "none",
            }}
          >
            ✦
          </div>

          <h1
            style={{
              fontSize: minDim * 0.16, // Responsive large text
              fontWeight: 900,
              color: accentColor,
              margin: 0,
              textAlign: "center",
              lineHeight: 1.05,
              textTransform: "uppercase",
              textShadow: textShadows,
              WebkitTextStroke: `4px #ffffff`,
              paintOrder: "stroke fill",
              filter: "drop-shadow(0px 25px 25px rgba(0,0,0,0.6))",
              transition: "none",
            }}
          >
            {title.split("\n").map((line, i) => (
              <React.Fragment key={i}>
                {line}
                <br />
              </React.Fragment>
            ))}
          </h1>
        </div>

        {/* Subtitle Card Plate */}
        <div
          style={{
            marginTop: 80,
            transform: `translateY(${subtitleY}px)`,
            opacity: subtitleOpacity,
            backgroundColor: "#ffffff",
            padding: "24px 48px",
            borderRadius: 100,
            boxShadow: `0 12px 0px ${shadowColor}, 0 25px 40px rgba(0,0,0,0.5)`,
            border: `8px solid ${accentColor}`,
            zIndex: 5,
            maxWidth: width * 0.85,
            transition: "none",
          }}
        >
          <h2
            style={{
              fontSize: minDim * 0.05, // Readable secondary sizing
              fontWeight: 800,
              color: backgroundColor,
              margin: 0,
              textAlign: "center",
              textTransform: "uppercase",
              letterSpacing: "0.06em",
              lineHeight: 1.2,
              transition: "none",
            }}
          >
            {subtitle}
          </h2>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default GameShowTitleCard;